  say(2.4,'落到伙伴身上，两只一起软下去。');pose(A,2.4,.13,{sy:.80,sx:1.2,rot:0,openL:.65,openR:.65});pose(B,2.4,.13,{sy:.65,sx:1.33,openL:.28,openR:.28,eyeY:-17});
